package com.iflytek.astron.console.hub.platform.run;

import java.io.InputStream;
import org.springframework.core.io.Resource;

/** Independent of Skill input storage. All keys are generated by the control plane. */
public interface TaskOutputStore {
    int MAX_FILE_BYTES = 32 * 1024 * 1024;
    void put(String key, InputStream input, long size, String sha256);
    Resource verified(String key, long size, String sha256);
    void remove(String key);
    static void checkKey(String key) {
        if(key==null || !key.matches("task-outputs/v1/[a-f0-9-]{36}/[a-f0-9-]{36}/[a-f0-9-]{36}"))
            throw new RunFailure("invalid_output_key");
    }
}
